#[tokio::test]
async fn dtmf_sent_timeout_fallback() {
    tokio::time::pause();
    let (tx, mut rx) = tokio::sync::broadcast::channel::<SipEvent>(16);
    let bus = EventBus { control: tx, raw_sip: None };

    // Spawn timer task
    let bus_clone = bus.clone();
    tokio::spawn(async move {
        tokio::time::sleep(std::time::Duration::from_millis(500)).await;
        bus_clone.publish(SipEvent {
            meta: EventMeta::dummy(),
            payload: SipEventPayload::DtmfSent(DtmfSentInfo {
                method: DtmfMethod::Rfc4733,
                digit: '5',
                status: Err(SentDtmfError::Timeout),
                pjsip_status: None,
            }),
        });
    });

    // Advance time
    tokio::time::advance(std::time::Duration::from_millis(500)).await;
    let ev = rx.recv().await.unwrap();
    match ev.payload {
        SipEventPayload::DtmfSent(info) => {
            assert_eq!(info.digit, '5');
            assert!(info.status.is_err());
        },
        _ => panic!("expected DtmfSent"),
    }
}

