UT: [Normal] SyncSourceAdapter wraps SyncAudioSource into AsyncAudioSource
  ```rust
  struct ConstSource(Vec<i16>, usize);
  impl SyncAudioSource for ConstSource {
      fn next_chunk(&mut self, buf: &mut [i16]) -> usize {
          if self.1 >= self.0.len() { return 0; }
          let n = (self.0.len() - self.1).min(buf.len());
          buf[..n].copy_from_slice(&self.0[self.1..self.1 + n]);
          self.1 += n;
          n
      }
  }
  let inner = ConstSource(vec![10i16; 4], 0);
  let mut adapter = SyncSourceAdapter::new(inner);
  let mut buf = [0i16; 4];
  let n = adapter.next_chunk(&mut buf).await;  // async call
  assert_eq!(n, 4);
  ```

